// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        // Ensure block.number % 15 != 0 so transfer does not happen
        vm.assume(blockNumber % 15 != 0);
        // Bound timestamp to reasonable values
        timestamp = bound(timestamp, 1, 1e12);
        // Set the block
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Record pastBlockTime before the call
        uint256 beforePastBlockTime = c.pastBlockTime();

        // Deal 10 ether to this contract and call fallback
        vm.deal(address(c), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Ensure call succeeded
        assertTrue(success);

        // Record pastBlockTime after the call
        uint256 afterPastBlockTime = c.pastBlockTime();

        // The rule: pastBlockTime should have increased by more than (block.timestamp - beforePastBlockTime)
        // Specifically, the new pastBlockTime = block.timestamp + 1, so it must be > block.timestamp
        // But since beforePastBlockTime could be anything, the condition is afterPastBlockTime > timestamp
        assertTrue(afterPastBlockTime > timestamp);
    }
}

